CREATE TABLE public.publisher_payment_policy (id boolean PRIMARY KEY DEFAULT true CHECK(id), version integer NOT NULL DEFAULT 1, effective_at timestamptz NOT NULL DEFAULT now(), minimum numeric(20,6) NOT NULL DEFAULT 50 CHECK(minimum>=50), verification_days integer NOT NULL DEFAULT 14 CHECK(verification_days>=14), weekday integer NOT NULL DEFAULT 1 CHECK(weekday BETWEEN 0 AND 6), hour_utc integer NOT NULL DEFAULT 9 CHECK(hour_utc BETWEEN 0 AND 23));
GRANT SELECT ON public.publisher_payment_policy TO anon,authenticated; GRANT ALL ON public.publisher_payment_policy TO service_role;
ALTER TABLE public.publisher_payment_policy ENABLE ROW LEVEL SECURITY; CREATE POLICY payment_policy_read ON public.publisher_payment_policy FOR SELECT TO anon,authenticated USING(true);
CREATE TABLE public.publisher_earnings_batches (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id), source text NOT NULL, period_start date NOT NULL, period_end date NOT NULL, gross numeric(20,6) NOT NULL CHECK(gross>=0), adjustment numeric(20,6) NOT NULL DEFAULT 0 CHECK(adjustment>=0 AND adjustment<=gross), net numeric(20,6) GENERATED ALWAYS AS (gross-adjustment) STORED, verification_started_at timestamptz NOT NULL DEFAULT now(), verification_ends_at timestamptz NOT NULL, status text NOT NULL DEFAULT 'under_verification' CHECK(status IN ('under_verification','on_hold','finalized')), approved boolean NOT NULL DEFAULT false, investigation_open boolean NOT NULL DEFAULT false, reconciliation_open boolean NOT NULL DEFAULT false, finalized_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,source,period_start,period_end), CHECK(period_end>=period_start));
GRANT SELECT ON public.publisher_earnings_batches TO authenticated; GRANT ALL ON public.publisher_earnings_batches TO service_role; ALTER TABLE public.publisher_earnings_batches ENABLE ROW LEVEL SECURITY; CREATE POLICY financial_read ON public.publisher_earnings_batches FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin')); CREATE INDEX ON public.publisher_earnings_batches(user_id);
CREATE TABLE public.publisher_earnings_adjustments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id), batch_id uuid NOT NULL REFERENCES public.publisher_earnings_batches(id), amount numeric(20,6) NOT NULL CHECK(amount>0), reason text NOT NULL, evidence text NOT NULL, evidence_key text NOT NULL UNIQUE, created_by uuid NOT NULL, reversed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.publisher_earnings_adjustments TO authenticated; GRANT ALL ON public.publisher_earnings_adjustments TO service_role; ALTER TABLE public.publisher_earnings_adjustments ENABLE ROW LEVEL SECURITY; CREATE POLICY financial_read ON public.publisher_earnings_adjustments FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin')); CREATE INDEX ON public.publisher_earnings_adjustments(user_id);
CREATE TABLE public.publisher_payment_accounts (user_id uuid PRIMARY KEY REFERENCES public.profiles(id), method public.payment_method, destination text, verified boolean NOT NULL DEFAULT false, on_hold boolean NOT NULL DEFAULT false, reason text, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.publisher_payment_accounts TO authenticated; GRANT ALL ON public.publisher_payment_accounts TO service_role; ALTER TABLE public.publisher_payment_accounts ENABLE ROW LEVEL SECURITY; CREATE POLICY financial_read ON public.publisher_payment_accounts FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.publisher_quality_reports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id), batch_id uuid NOT NULL REFERENCES public.publisher_earnings_batches(id), impressions bigint NOT NULL DEFAULT 0 CHECK(impressions>=0), validated_impressions bigint NOT NULL DEFAULT 0 CHECK(validated_impressions>=0), invalid_impressions bigint NOT NULL DEFAULT 0 CHECK(invalid_impressions>=0), status text NOT NULL DEFAULT 'Monitoring' CHECK(status IN ('Clean','Monitoring','Under Review','Adjustment Applied','Restricted')), evidence text, created_at timestamptz NOT NULL DEFAULT now(), CHECK(validated_impressions+invalid_impressions<=impressions));
GRANT SELECT ON public.publisher_quality_reports TO authenticated; GRANT ALL ON public.publisher_quality_reports TO service_role; ALTER TABLE public.publisher_quality_reports ENABLE ROW LEVEL SECURITY; CREATE POLICY financial_read ON public.publisher_quality_reports FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin')); CREATE INDEX ON public.publisher_quality_reports(user_id);
CREATE TABLE public.publisher_adjustment_appeals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id), adjustment_id uuid NOT NULL REFERENCES public.publisher_earnings_adjustments(id), reason text NOT NULL, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')), resolution text, resolved_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(adjustment_id));
GRANT SELECT ON public.publisher_adjustment_appeals TO authenticated; GRANT ALL ON public.publisher_adjustment_appeals TO service_role; ALTER TABLE public.publisher_adjustment_appeals ENABLE ROW LEVEL SECURITY; CREATE POLICY financial_read ON public.publisher_adjustment_appeals FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin')); CREATE INDEX ON public.publisher_adjustment_appeals(user_id);
CREATE TABLE public.publisher_payment_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id), batch_id uuid REFERENCES public.publisher_earnings_batches(id), payment_id uuid REFERENCES public.payments(id), kind text NOT NULL, amount numeric(20,6) NOT NULL DEFAULT 0, reason text NOT NULL, actor_id uuid, idempotency_key text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.publisher_payment_events TO authenticated; GRANT ALL ON public.publisher_payment_events TO service_role; ALTER TABLE public.publisher_payment_events ENABLE ROW LEVEL SECURITY; CREATE POLICY financial_read ON public.publisher_payment_events FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin')); CREATE INDEX ON public.publisher_payment_events(user_id);
CREATE TABLE public.publisher_policy_acceptances (user_id uuid NOT NULL REFERENCES public.profiles(id), version integer NOT NULL, accepted_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,version));
GRANT SELECT ON public.publisher_policy_acceptances TO authenticated; GRANT ALL ON public.publisher_policy_acceptances TO service_role; ALTER TABLE public.publisher_policy_acceptances ENABLE ROW LEVEL SECURITY; CREATE POLICY financial_read ON public.publisher_policy_acceptances FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
ALTER TABLE public.payments ADD COLUMN ledger_managed boolean NOT NULL DEFAULT false, ADD COLUMN lifecycle_status text, ADD COLUMN idempotency_key text, ADD COLUMN earnings_period_start date, ADD COLUMN earnings_period_end date, ADD COLUMN confirmed_at timestamptz, ADD COLUMN reconciled_at timestamptz, ADD COLUMN hold_reason text;
CREATE UNIQUE INDEX payments_idempotency ON public.payments(idempotency_key) WHERE idempotency_key IS NOT NULL;
REVOKE INSERT,UPDATE,DELETE ON public.payments FROM authenticated;
CREATE INDEX ON public.publisher_earnings_batches(status,verification_ends_at);
CREATE OR REPLACE FUNCTION public.payment_immutable() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN RAISE EXCEPTION 'Financial history is immutable; record a reversal instead'; END $$;
CREATE TRIGGER immutable_payment_events BEFORE UPDATE OR DELETE ON public.publisher_payment_events FOR EACH ROW EXECUTE FUNCTION public.payment_immutable();